1	// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, re-evaluate
3	// the precondition (the scheduler run asked once at the anchor; a chained stage
4	// re-derives world state rather than trusting a verdict passed forward), then on
5	// a go run code-work and either converge (agentless) or hand off to an agent
6	// session; on a no-go close the item with the reason on record — the next
7	// occurrence is the scheduler run's ask at the task's next anchor (#1115).
8	//
9	// An executor's whole interface is issue read/write plus the repo at HEAD, which
10	// is what makes it platform-agnostic: the reference deployment is a job in the
11	// vendored workflows (the scheduler run's post-scheduler run drain, and a `labeled`-event run for
12	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
13	// enumerates executors; identity is self-declared in the claim comment.
14	//
15	// The pure decisions live at the top and test with fixtures; the shell below is
16	// the GitHub/code-work/invocation I/O around them.
17	
18	import { pathToFileURL } from 'node:url';
19	import { isSuspended, suspendedNotice } from './suspend.mjs';
20	import { readyDependents } from './readiness.mjs';
21	import { HEARTBEAT_MS, heartbeatComment, withHeartbeat } from './heartbeat.mjs';
22	import { renderTaskExec } from '../run-record.mjs';
23	import { swapStatus, clearStatus } from './apply-status.mjs';
24	import {
25	  READY, URGENT, EXECUTING, AGENT, NEEDS_HUMAN,
26	  STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, isStatus,
27	  TASK_DONE, TASK_OBSOLETE, QUEUE_LABELS, QUEUED_LABEL, isStandingItem,
28	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE, triageLabelFor,
29	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
30	  parseWorkItemTitle, isWorkItemTitle, parseWorkItemBody, parseContextLines, mergeContext, withNotBefore, withSection, editItemBody, hasLabel, DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS,
31	  LAST_VERDICT_HEADING, lastVerdictLines } from './work-item.mjs';
32	
33	const titleOf = (item) => (item.title ?? '').trim();
34	// An item somebody is executing — the executor holds it, or the agent it handed to
35	// does. Decoded, never a literal label test: the item may wear any engine's spelling.
36	const running = (item) => isStatus(item, STATUS_RUNNING_EXECUTOR) || isStatus(item, STATUS_RUNNING_AGENT);
37	// WHICH TASK AN ITEM NAMES. A filed `[claudinite-work]` item says so in its title;
38	// a marked issue (DESIGN §16.1) keeps its own human title and names its task in the
39	// machine block's first line, so the id comes from the task whose worker path that
40	// is. `pathTo` is that lookup, injected because only the run holds the task set.
41	const taskIdOf = (item, pathTo = () => null) => {
42	  const p = parseWorkItemTitle(item.title);
43	  if (p) return `${p.pack}/${p.task}`;
44	  return pathTo(parseWorkItemBody(item.body).taskPath) ?? null;
45	};
46	
47	// The pick order (DESIGN §6.1): urgent first, then RANDOM among the ready, with
48	// two skip rules read live at pick time. Random rather than oldest-first because
49	// nothing leans on FIFO aging — the stale-ready escalation is period-scale — while
50	// a deterministic order lets one unlucky head dominate every run of a chain
51	// (DESIGN §15.20).
52	//
53	//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
54	//    item executing or handed to an agent — one task, one execution at a time,
55	//    while a fan-out's distinct qualifiers still parallelize.
56	//  - THE `after` YIELD (S23): skip a scheduled item whose task declares `after:
57	//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
58	//    A declined upstream holds nothing back — it has no item at all (a no files
59	//    only a board row, #1115) — and neither does one sitting `needs-human`: a
60	//    broken upstream must not halt its dependents indefinitely.
61	//
62	// `open` is every open work item; `taskAfter(id)` gives a task's declared
63	// upstreams as `<pack>/<task>` ids, and `frequencyOf(id)` that task's declared
64	// frequency at HEAD — which is half of what says whether an item is a standing
65	// occurrence or an ad-hoc run (§15.26). `random` is the tie-break draw, injected
66	// so a test can pin an order the production call deliberately does not have.
67	export function pickOrder(open = [], { taskAfter = () => [], frequencyOf = () => null, random = Math.random, pathTo = () => null } = {}) {
68	  const idOf = (item) => taskIdOf(item, pathTo);
69	  const live = (item) => [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT].some((s) => isStatus(item, s));
70	  const standing = (item) => isStandingItem(item, frequencyOf(idOf(item)));
71	  const liveUpstream = (upstreamId) => open.some((o) =>
72	    idOf(o) === upstreamId && standing(o) && live(o));
73	  // One draw per item, taken once: a comparator that called `random()` per
74	  // comparison would not be a consistent ordering, and `Array.sort` on one is
75	  // free to produce anything at all.
76	  const draw = new Map(open.map((i) => [i.number, random()]));
77	
78	  return open
79	    .filter((i) => isStatus(i, STATUS_READY))
80	    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
81	      && running(o)))
82	    .filter((i) => {
83	      if (!standing(i)) return true;
84	      return !taskAfter(idOf(i)).some(liveUpstream);
85	    })
86	    .sort((a, b) =>
87	      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
88	      || draw.get(a.number) - draw.get(b.number));
89	}
90	
91	// The claim comment carries WHO and WHEN — the executor id and its run URL —
92	// because executor identity is an unbounded set and must never become a label
93	// (DESIGN §4).
94	export const claimComment = ({ executor, runUrl, at }) =>
95	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
96	
97	// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
98	// each an implicit assumption made explicit:
99	//
100	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
101	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
102	//    comment ids are server-assigned and strictly increasing — a total order the
103	//    protocol gets for free. Nothing here compares runner clocks.
104	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
105	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
106	//    and revert leaves one), and arbitrating over all of them makes a dead claim
107	//    outrank every future live claimant — the item then livelocks through reclaim
108	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
109	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
110	//    owner; it can only leave an item with no state label, which the janitor
111	//    repairs.
112	export function claimWinner(comments = []) {
113	  const sorted = [...comments].sort((a, b) => a.id - b.id);
114	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
115	  const claims = sorted
116	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
117	    .filter((c) => !boundary || c.id > boundary.id);
118	  return claims[0] ?? null;
119	}
120	
121	// After WINNING a claim, re-verify the pick filters against live state (F15). The
122	// filters read possibly-stale state, so two executors can pass them simultaneously
123	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
124	// an upstream and its dependent. The per-item lease cannot see that: it protects
125	// one item, not one title. If a conflicting item now holds an EARLIER claim
126	// (comment id — the same arbiter the lease trusts), this executor reverts its own
127	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
128	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [], frequencyOf = () => null, pathTo = () => null } = {}) {
129	  const idOf = (i) => taskIdOf(i, pathTo);
130	  const standing = (i) => isStandingItem(i, frequencyOf(idOf(i)));
131	  const upstreams = standing(item) ? taskAfter(idOf(item)) : [];
132	  return others.some((o) => {
133	    if (o.number === item.number) return false;
134	    if (!running(o)) return false;
135	    const conflicting = titleOf(o) === titleOf(item)
136	      || (upstreams.includes(idOf(o)) && standing(o));
137	    return conflicting && o.claimId != null && o.claimId < myClaimId;
138	  });
139	}
140	
141	// The no-go outcome (DESIGN §6.4, as amended by #1115): every decline CLOSES
142	// the item with the reason. The roll — `Not-before` stamped, open-blocked,
143	// waiting out the period — is gone: "asked and declined" lives on the schedule
144	// board, and a scheduled item's next occurrence is the scheduler run's ask at
145	// its next anchor (the closed-at half of the occurrence guard keeps this
146	// period consumed). `standing` marks whether the close should say so.
147	// The `(item, task, schedule, now, reason)` signature is kept — callers and
148	// fielded tests pass all five, and the standing/ad-hoc distinction still
149	// shapes the close's wording.
150	export function noGoPlan(item, task, schedule, now, reason) {
151	  return {
152	    kind: 'close',
153	    outcome: TASK_OBSOLETE,
154	    stateReason: 'not_planned',
155	    reason,
156	    standing: isStandingItem(item, task?.decl?.frequency),
157	  };
158	}
159	
160	// --- the shell ----------------------------------------------------------------
161	
162	const nowIso = () => new Date().toISOString();
163	
164	// ONE EXECUTOR RUN PERFORMS ONE ITEM (DESIGN §6, §10, decision §15.22). Not a
165	// configured maximum — the essence of an executor: it claims one item, sees it to
166	// its settle, and ends. Capacity is executor width, and the queue drains as a
167	// CHAIN of runs, each cause on the record (§10): the scheduler run's own drain job, a
168	// label event, the close-time drain, this run's own `redispatch`, and the
169	// workflow's failure-continuation job when a run dies before reaching it.
170	//
171	// A run that never gets its item — nothing pickable, or another executor holds
172	// this episode's earlier claim — ends without dispatching anything. Retrying a
173	// lost race here would be a second pick attempt racing the very executor that
174	// won, and re-dispatching over a claim we just reverted is a two-executor
175	// dispatch loop; in both cases the winner's own chain (or the scheduler run behind it)
176	// carries the queue.
177	//
178	// Injected seams keep the run testable end to end without GitHub, code-work
179	// subprocesses or an invocation endpoint.
180	export async function runExecutor({
181	  gh, repo, root, config, tasks, executorId, runUrl = null,
182	  now = () => new Date(), random = Math.random, heartbeatMs = HEARTBEAT_MS,
183	  collectSignalsFor, runTaskCodeWork, invokeAgent, redispatch = null, log = console.log,
184	}) {
185	  const api = await import('../github.mjs');
186	  const { listOpenWorkItems } = await import('./read.mjs');
187	  const schedule = config.taskScheduler;
188	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
189	  const taskAfter = (id) => byId.get(id)?.decl?.after ?? [];
190	  const frequencyOf = (id) => byId.get(id)?.decl?.frequency ?? null;
191	  // A marked issue names its task by worker path, so the run needs the inverse of
192	  // the id map — built from the same task set, so a path this repo does not carry
193	  // resolves to nothing and the item is malformed rather than guessed at.
194	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
195	  const pathTo = (p) => byPath.get(p) ?? null;
196	  const done = [];
197	
198	  const open = await listOpenWorkItems(gh, repo);
199	  const candidate = pickOrder(open, { taskAfter, frequencyOf, random, pathTo })[0];
200	  if (!candidate) return done;
201	
202	  // --- claim: the verified lease --------------------------------------------
203	  await swapStatus(api, gh, repo, candidate, STATUS_READY, EXECUTING);
204	  await api.comment(gh, repo, candidate.number, claimComment({
205	    executor: executorId, runUrl, at: nowIso(),
206	  }));
207	  const comments = await api.listComments(gh, repo, candidate.number);
208	  const winner = claimWinner(comments);
209	  const mine = [...comments]
210	    .sort((a, b) => a.id - b.id)
211	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER) && (c.body ?? '').includes(`executor \`${executorId}\``))
212	    .at(-1);
213	  if (!winner || winner.id !== mine?.id) {
214	    // The loser reverts nothing — the winner's labels already stand. It does
215	    // strike its own claim (F24): letting go covers losing too, and a claim left
216	    // behind here outlives the winner's episode and becomes the earliest of the
217	    // NEXT one, moving the livelock one episode along.
218	    await strikeClaim(api, gh, repo, mine);
219	    log(`- #${candidate.number}: another executor holds this episode's earliest claim — this run stands down`);
220	    return done;
221	  }
222	
223	  // --- post-claim re-verify (F15) -------------------------------------------
224	  const others = await withClaimIds(api, gh, repo, await listOpenWorkItems(gh, repo), candidate.number);
225	  if (conflictsWithEarlierClaim(candidate, winner.id, others, { taskAfter, frequencyOf, pathTo })) {
226	    await api.comment(gh, repo, candidate.number,
227	      `${EPISODE_MARKER}\nReverting this claim: a conflicting item holds an earlier claim this cycle. Returning the item to the queue.`);
228	    await swapStatus(api, gh, repo, candidate, STATUS_RUNNING_EXECUTOR, READY);
229	    log(`- #${candidate.number}: reverted — a conflicting item claimed earlier`);
230	    return done;
231	  }
232	
233	  const outcome = await executeItem({
234	    api, gh, repo, root, config, schedule, byId, pathTo, item: candidate, executorId,
235	    claim: winner, now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
236	  });
237	  done.push({ issue: candidate.number, outcome });
238	
239	  // --- the chain: hand the remainder to a fresh run -------------------------
240	  // Read live, after the settle: this item's convergence may have readied a
241	  // dependent, and another executor may have taken what was pickable when this
242	  // run started.
243	  if (redispatch) {
244	    const left = pickOrder(await listOpenWorkItems(gh, repo), { taskAfter, frequencyOf, random, pathTo });
245	    if (left.length) {
246	      const res = await redispatch();
247	      log(res?.ok
248	        ? `- ${left.length} item(s) still pickable — dispatched a fresh executor run`
249	        : `! ${left.length} item(s) still pickable but the re-dispatch failed (${res?.status ?? 'no status'}) — the scheduler run's drain is the backstop`);
250	    }
251	  }
252	  return done;
253	}
254	
255	// The claim id of each live item, so the post-claim verify can compare episodes.
256	// One comment read per conflicting-looking item, not per item in the repo.
257	async function withClaimIds(api, gh, repo, items, selfNumber) {
258	  const out = [];
259	  for (const i of items) {
260	    if (i.number === selfNumber || !running(i)) { out.push(i); continue; }
261	    const winner = claimWinner(await api.listComments(gh, repo, i.number));
262	    out.push({ ...i, claimId: winner?.id ?? null });
263	  }
264	  return out;
265	}
266	
267	// One claimed item, from validation through to a terminal state (or a hand-off).
268	async function executeItem({
269	  api, gh, repo, root, config, schedule, byId, pathTo = () => null, item, executorId, claim,
270	  now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
271	}) {
272	  // What a close needs beyond the item itself: the clock for a dependent's
273	  // `Not-before`, and somewhere to say what it released.
274	  const ctx = { now, log };
275	  const parsed = parseWorkItemTitle(item.title);
276	  const { taskPath } = parseWorkItemBody(item.body);
277	  // A marked issue's identity is its machine block, not its title (§16.1): the id
278	  // is whichever task owns the worker path the block names.
279	  const id = parsed ? `${parsed.pack}/${parsed.task}` : pathTo(taskPath);
280	  const task = id ? byId.get(id) : null;
281	  // The exec record joins back to the work by pack and task, which a marked issue's
282	  // human title cannot supply — so the resolved id travels with the item.
283	  item.taskId = id;
284	
285	  // --- validate in code, before anything trusts the issue ------------------
286	  if (!taskPath || (!parsed && !id)) {
287	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
288	      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.', 'invalid');
289	    return 'needs-human';
290	  }
291	  if (!task) {
292	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
293	      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`, 'task-gone', ctx);
294	    return 'obsolete';
295	  }
296	  if (task.taskPath !== taskPath) {
297	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
298	      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`, 'invalid');
299	    return 'needs-human';
300	  }
301	
302	  // --- the single precondition evaluation (DESIGN §6.4) --------------------
303	  const at = now();
304	  const fields = parseWorkItemBody(item.body);
305	  // The signals are collected FOR THIS OCCURRENCE, and the precondition judges over
306	  // it: a request item's verdict is about the issue it names, which no signal bundle
307	  // can single out on its own (DESIGN §16.4).
308	  const signals = await collectSignalsFor(task, at, item);
309	  const verdict = evaluatePrecondition(task, signals, config.packConfig?.[task.pack] ?? {}, fields);
310	
311	  // A PRECONDITION THAT COULD NOT ANSWER IS A RUN FAILURE, NOT A VERDICT (F27). A
312	  // decline is a decision about the world; one taken on an API that would not answer
313	  // is a guess, and its write-backs cannot land — for a request that would strand
314	  // the issue armed-but-queued forever, the request silently eaten. So the item
315	  // parks open in the failure lane, where the ordinary re-queue lever retries it
316	  // once the API recovers, and nothing is written to whatever it could not read.
317	  if (verdict.error) {
318	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
319	      `This run could not be decided: ${verdict.error}\n\nNothing ran and nothing was written. Re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`) once the cause has cleared.`);
320	    log(`! #${item.number} ${id}: the precondition could not answer — ${verdict.error}`);
321	    return 'needs-human';
322	  }
323	
324	  if (verdict.run !== true) {
325	    const plan = noGoPlan(item, task, schedule, at, verdict.reason || 'no work');
326	    // A DECLINED REQUEST IS DISARMED IN THE SAME CONVERGENCE (DESIGN §16.5).
327	    // Nothing else would: an issue left carrying `claude-queued` after its run was
328	    // refused is one no later scheduler run adopts and no person is told about, and one
329	    // whose mark — if re-applied — walks into the same refusal forever.
330	    // A LEGACY shadow item wrote its decline back to the issue it named. A marked
331	    // issue IS the item, so the decline's comment and its `rejected` status already
332	    // land where the person is looking and there is nothing to mirror (§16.5).
333	    if (fields.request && fields.request !== item.number) {
334	      await declineRequest(api, gh, repo, fields.request, item.number, plan.reason);
335	    }
336	    // A DECLINE IS A COMPLETED RUN, not a failure: the executor asked, got a
337	    // no, and closed the occurrence — so the record says `success` and the
338	    // reason sits beside it in the same comment.
339	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
340	      `The precondition declined: ${plan.reason}`
341	      + (plan.standing
342	        ? '\n\nThis task\'s next occurrence is decided at its next anchor; declined occurrences are recorded on the schedule board.'
343	        : ''), 'success', ctx);
344	    return 'obsolete';
345	  }
346	
347	  // --- code-work (unchanged contract), then converge or hand off -------------
348	  // The item's OWN Context is scope too, not decoration: an operator's parameters
349	  // (`create-work-item --context "REPOS=Alpha Beta"`) live there and nowhere else,
350	  // so code-work sees the union of what the item was created with and what this
351	  // occurrence's precondition added. Passing only the verdict's half is what made
352	  // a hand-created item's parameters unreachable (#974).
353	  const context = mergeContext(parseContextLines(item.body), verdict.context ?? []);
354	  if (task.decl.code_work) {
355	    // The work step may legitimately run for hours (§15.15). While it does, the
356	    // item's only sign of life is this beat — which is also what the scheduler run's leash
357	    // measures, so a long run is legal rather than reclaimed underneath itself.
358	    const result = await withHeartbeat(() => runTaskCodeWork(task, { item, context }), {
359	      intervalMs: heartbeatMs,
360	      log,
361	      beat: (minutes) => api.comment(gh, repo, item.number,
362	        heartbeatComment({ executor: executorId, at: nowIso(), minutes })),
363	    });
364	    if (!result.ok) {
365	      // The worker's own verdict routes the park where it left one; a worker that
366	      // said nothing about why it failed is a `failure` — the lane that means
367	      // "someone reads the trace", which is the only safe default for a run whose
368	      // cause is unknown.
369	      await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, triageLabelFor(result.triage?.kind), claim,
370	        `Code-work failed: ${result.why}${result.triage?.detail ? `\n\nThe worker's own verdict: ${result.triage.detail}` : ''}`
371	        + `${result.detail ? `\n\n\`\`\`\n${result.detail}\n\`\`\`` : ''}`);
372	      return 'needs-human';
373	    }
374	    if (result.missingSecrets?.length) {
375	      await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_ACTION, claim,
376	        `This task declares repo Actions secrets that are not configured: ${result.missingSecrets.join(', ')}. Set them in repo settings and re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`).`);
377	      return 'needs-human';
378	    }
379	    if (!result.agentRequested) {
380	      // A run that deliberately left an UNMERGED PR is not finished, it is waiting
381	      // on a person — so the item stays OPEN at `task:needs-human-approval` rather
382	      // than closing as delivered. It does not hold the task's lane while it waits
383	      // (`isBlockingPark`): the next occurrence is filed on schedule around it, so
384	      // an unreviewed PR delays nobody but its reviewer.
385	      if (result.openPr) {
386	        await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_APPROVAL, claim,
387	          `Code-work did this run's work and opened a PR for you to approve:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
388	          + `\n\nMerge or close #${result.openPr}, then close this item. This task keeps running on schedule meanwhile.`, null);
389	        return 'needs-human';
390	      }
391	      await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_DONE, 'completed',
392	        result.delivered?.length
393	          ? `Code-work did this run's work and left:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
394	          : 'Code-work did this run\'s work; no agent was needed.', 'success', ctx);
395	      return TASK_DONE;
396	    }
397	    return handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log });
398	  }
399	
400	  // An agentless task with no code-work does nothing (the contract forbids it).
401	  if (task.decl.agent_model === 'none') {
402	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
403	      'This task is agentless but declares no code_work, so there is nothing to run — a contract-forbidden shape that reached the queue.', 'invalid');
404	    return 'needs-human';
405	  }
406	  return handOff({ api, gh, repo, item, task, id, context, result: {}, executorId, claim, invokeAgent, config, log });
407	}
408	
409	// Run one task's precondition. THE only place a precondition is ever called, so a
410	// test that drives this drives what production drives — a precondition first
411	// written to take `{ signals }` passed its own direct-call test and threw on every
412	// real run, which is the failure this seam exists to make impossible.
413	//
414	// A throwing precondition converges to a no-go with the error as its reason: one
415	// task's bad verdict is that item's problem, never the executor's.
416	export function evaluatePrecondition(task, signals, packConfig = {}, item = null) {
417	  try {
418	    return task.decl.precondition(signals, packConfig, item) ?? {};
419	  } catch (e) {
420	    return { run: false, reason: `precondition threw: ${e.message}` };
421	  }
422	}
423	
424	// @deprecated The write-back a refused SHADOW item's issue got — one comment saying
425	// why, and the queued label off, so the request was disarmed rather than left
426	// looking pending. Nothing writes it for an item filed under the one-issue model,
427	// where the item and the issue are the same object; it stays for the shadow items
428	// still draining, whose issue is a different one (DESIGN §16.5).
429	async function declineRequest(api, gh, repo, request, item, reason) {
430	  await api.comment(gh, repo, request,
431	    `Not implementing this: ${reason}\n\nThe queued run (#${item}) is closed and \`${QUEUED_LABEL}\` is removed. `
432	    + 'If this was wrong, mark the issue again — a request is only run when the person who opened it, or somebody who commented `/claude go`, has push access here.');
433	  await api.removeLabel(gh, repo, request, QUEUED_LABEL);
434	}
435	
436	// @deprecated The roll retired with #1115 — nothing writes this any more. Kept
437	// exported because bodies the fielded roll wrote are stored data: the
438	// round-trip test over this writer is what pins `parseLastVerdict`'s decode,
439	// which the migration and the dashboard still read.
440	export function rollBody(body, until, reason, at) {
441	  const stamped = withNotBefore(body, until);
442	  return withSection(stamped, LAST_VERDICT_HEADING, lastVerdictLines({ at, reason, until }));
443	}
444	
445	// Hand off to an agent session (DESIGN §6.6). ONE call per item, ever — which is
446	// what lets this be as short as it is. The nonce goes on the item before the call
447	// and travels in the payload, so the session can prove the fire it arrived on is
448	// the hand-off this item recorded and stop if it is not.
449	async function handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log }) {
450	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
451	  // Every section lands in the machine's half of the body — the whole body for a
452	  // filed item, the machine block for a marked issue, whose prose is the person's.
453	  const body = editItemBody(item.body, (machine) => {
454	    let out = machine;
455	    if (context.length) out = withSection(out, 'Context', context);
456	    if (result.delivered?.length) out = withSection(out, DELIVERED_HEADING, result.delivered, LEGACY_DELIVERED_HEADINGS);
457	    if (result.reason) out = withSection(out, 'Why the agent is here', [result.reason]);
458	    return out;
459	  });
460	  await gh(`/repos/${repo}/issues/${item.number}`, { method: 'PATCH', body: { body } });
461	
462	  await swapStatus(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, AGENT);
463	  await api.comment(gh, repo, item.number,
464	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);
465	
466	  const invocation = await invokeAgent({ task, item, nonce, config });
467	  if (invocation.ok) {
468	    await api.comment(gh, repo, item.number,
469	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
470	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
471	    return 'agent';
472	  }
473	  if (invocation.answered) {
474	    // The endpoint refused, so no session exists and none will: a token, a URL or
475	    // a routine is wrong, and every future pick would be refused the same way.
476	    await converge(api, gh, repo, item, STATUS_RUNNING_AGENT, NEEDS_HUMAN_ACTION, claim,
477	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`).`);
478	    return 'needs-human';
479	  }
480	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
481	  // may have started a session. Re-queueing here is what would put two sessions on
482	  // one item, and converging to triage would kill a run that is very possibly
483	  // alive. So the item STAYS with the agent and says the outcome is unknown —
484	  // whichever way it went is then settled by a rule that already exists: a session
485	  // that started converges the item, and one that never did leaves the item silent
486	  // until the janitor's agent leash sweeps it to triage.
487	  await api.comment(gh, repo, item.number,
488	    `The agent invocation got no answer: ${invocation.error}\n\n`
489	    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
490	    + `If a session did start it will converge this item; if it did not, the janitor's agent leash brings this item to \`${NEEDS_HUMAN}\` within a few hours.`);
491	  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
492	  return 'unknown';
493	}
494	
495	// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (DESIGN §6.2, F24). An executor
496	// that stops owning an item without closing it — the roll, and every
497	// `needs-human` park — strikes its own claim by appending the episode marker to
498	// it. `claimWinner` already treats the last marker as the boundary, so a struck
499	// claim stops outranking anything and the next claimant wins on its first try.
500	//
501	// APPENDING rather than commenting is what lets the roll stay silent (§5): an
502	// hourly task that declines every hour adds no timeline entry. A successful
503	// hand-off deliberately does NOT strike — the episode is still live, owned by the
504	// agent session — and neither does a close, since nothing re-claims a closed item.
505	//
506	// Struck BEFORE the label swap, so the crash window degrades the safe way: an
507	// executor that dies between the two leaves the item `task:executing` with a
508	// spent claim, which the scheduler run's leash reclaim already recovers. Striking after
509	// would leave exactly the state this fixes — parked, re-queued by a human, and
510	// unclaimable forever.
511	async function strikeClaim(api, gh, repo, claim) {
512	  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
513	  await api.editComment(gh, repo, claim.id,
514	    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
515	}
516	
517	// Every exit converges the item exactly once, with one comment saying what
518	// happened — the terminal-state discipline the incidents bought. The claim sits
519	// before the body so every state argument is grouped ahead of the prose.
520	//
521	// THE COMMENT CARRIES THE EXECUTION RECORD (DESIGN §6.5, §15.18). Actions logs
522	// expire, and for an agentless run — the majority — the item is the only durable
523	// trace there will ever be, so the record goes where the item is rather than into
524	// a log that ages out. The bracketed field is this item's issue number, which is
525	// the only join from a record back to the work it describes.
526	// A status of `null` writes NO record, and that is the honest answer for a park
527	// that is not a failure: the vocabulary's `success` means "ran to completion and
528	// the issue was closed" and `failed` means the run broke, so an approval park —
529	// a run that succeeded and left a PR for a person — is neither. Absence is a
530	// state of its own; inventing a fifth status is a change to stored data every
531	// decoder in the fleet would have to learn.
532	const recordFor = (item, status) => {
533	  // `item.taskId` is the resolved id — a marked issue's title names no task, so the
534	  // title parse alone would silently drop the record for every request run.
535	  const id = item.taskId ?? null;
536	  const parsed = status
537	    ? (id ? { pack: id.split('/')[0], task: id.split('/').slice(1).join('/') } : parseWorkItemTitle(item.title))
538	    : null;
539	  return parsed
540	    ? `\n\n\`\`\`\n${renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })}\n\`\`\``
541	    : '';
542	};
543	
544	// Park an item for a human. BOTH labels, always: `needs-human` is the state every
545	// guard and sweep reads, `triage` is what the human is being asked for.
546	async function converge(api, gh, repo, item, from, triage, claim, body, status = 'failed') {
547	  await strikeClaim(api, gh, repo, claim);
548	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
549	  await swapStatus(api, gh, repo, item, from, NEEDS_HUMAN);
550	  await api.addLabel(gh, repo, item.number, triage);
551	}
552	
553	// A close is also the moment a dependent may become due (§15.19): whoever closes
554	// an item releases what it was holding, in code, and the run's own re-dispatch
555	// then finds it. The scheduler run stays the backstop for every close this code never
556	// performs — a human's, or a session that stopped early.
557	async function close(api, gh, repo, item, from, outcome, stateReason, body, status, ctx = {}) {
558	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
559	  await clearStatus(api, gh, repo, item, from);
560	  await api.addLabel(gh, repo, item.number, outcome);
561	  // A MARKED ISSUE IS NOT THE RUN'S TO CLOSE (§16.1, §16.5). The item's terminal
562	  // status stands on the still-open issue: the run's verdict is about the run, and
563	  // whether the issue is finished belongs to the person who opened it. Nothing is
564	  // released either — a dependent waits for that issue to close, and it has not.
565	  if (!isWorkItemTitle(item.title)) return;
566	  await api.closeIssue(gh, repo, item.number, stateReason);
567	  await readyDependents(api, gh, repo, item.number, ctx);
568	}
569	
570	// --- CLI ----------------------------------------------------------------------
571	
572	async function main() {
573	  // THE OPERATOR HOLD, FIRST ACT (§15.24) — before the config load, before the
574	  // first API call, so a held queue reads nothing and writes nothing rather than
575	  // deriving the world and then declining to act on it.
576	  if (isSuspended()) { console.log('## Claudinite executor\n'); console.log(suspendedNotice()); return; }
577	  const { makeGh, actionRepoContext, EXECUTOR_WORKFLOW_FILE } = await import('../signals/gh.mjs');
578	  const { discoverTasks } = await import('../discover.mjs');
579	  const { loadConfig, isDormant } = await import('../../checks/helpers/repo-context.mjs');
580	  const { ensureLabels, dispatchWorkflow } = await import('../github.mjs');
581	  const { collectSignalsForTask } = await import('./signals.mjs');
582	  const { codeWorkRunner } = await import('./code-work-run.mjs');
583	  const { agentInvoker } = await import('./invoke.mjs');
584	
585	  const root = process.cwd();
586	  const { repo, defaultBranch } = actionRepoContext();
587	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
588	  const config = loadConfig(root);
589	
590	  console.log('## Claudinite executor\n');
591	  if (isDormant(config)) {
592	    console.log('- this project declares itself dormant — nothing is picked up');
593	    return;
594	  }
595	
596	  const gh = makeGh();
597	  const { tasks, errors } = await discoverTasks(root, config);
598	  for (const e of errors) console.log(`! ${e.what}`);
599	  await ensureLabels(gh, repo, QUEUE_LABELS);
600	
601	  const runUrl = process.env.GITHUB_RUN_ID
602	    ? `${process.env.GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${process.env.GITHUB_RUN_ID}`
603	    : null;
604	
605	  const done = await runExecutor({
606	    gh, repo, root, config, tasks,
607	    executorId: process.env.CLAUDINITE_EXECUTOR_ID || `actions-${process.env.GITHUB_RUN_ID ?? 'local'}`,
608	    runUrl,
609	    collectSignalsFor: collectSignalsForTask({ gh, repo, root, config, defaultBranch }),
610	    runTaskCodeWork: codeWorkRunner({ root, repo, defaultBranch }),
611	    invokeAgent: agentInvoker({ repo, config }),
612	    redispatch: () => dispatchWorkflow(gh, repo, EXECUTOR_WORKFLOW_FILE, defaultBranch),
613	  });
614	
615	  console.log(done.length
616	    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
617	    : '- nothing ready to pick up');
618	}
619	
620	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
621	  main().catch((e) => { console.error(e); process.exit(1); });
622	}
