  gh, repo, root, config, tasks, executorId, runUrl = null,
  now = () => new Date(), random = Math.random, heartbeatMs = HEARTBEAT_MS,
  collectSignalsFor, runTaskCodeWork, invokeAgent, redispatch = null, log = console.log,
}) {

